import { NextRequest, NextResponse } from "next/server";
import nodemailer from "nodemailer";

export async function POST(req: NextRequest) {
  try {
    const { name, email, subject, message } = await req.json();

    if (!name || !email || !subject || !message) {
      return NextResponse.json({ error: "All fields are required." }, { status: 400 });
    }

    const transporter = nodemailer.createTransport({
      host: "smtp.gmail.com",
      port: 465,
      secure: true,
      auth: {
        user: "sonnybst@gmail.com",
        pass: process.env.GMAIL_APP_PASSWORD,
      },
    });

    await transporter.sendMail({
      from: '"Portfolio Contact" <sonnybst@gmail.com>',
      to: "sonnybst@gmail.com",
      replyTo: email,
      subject: `[Portfolio] ${subject}`,
      html: `
        <!DOCTYPE html>
        <html>
        <body style="margin:0;padding:0;background:#f4f4f5;font-family:Arial,sans-serif;">
          <table width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5;padding:40px 0;">
            <tr><td align="center">
              <table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);">

                <!-- Header -->
                <tr>
                  <td style="background:linear-gradient(135deg,#3b82f6,#8b5cf6);padding:32px 40px;">
                    <p style="margin:0;color:#ffffff;font-size:13px;text-transform:uppercase;letter-spacing:2px;opacity:0.8;">Portfolio Message</p>
                    <h1 style="margin:8px 0 0;color:#ffffff;font-size:24px;font-weight:700;">New Contact Request</h1>
                  </td>
                </tr>

                <!-- Sender Info -->
                <tr>
                  <td style="padding:32px 40px 0;">
                    <table width="100%" cellpadding="0" cellspacing="0">
                      <tr>
                        <td style="padding:12px;background:#f8fafc;border-radius:8px;border-left:4px solid #3b82f6;">
                          <p style="margin:0 0 4px;color:#64748b;font-size:11px;text-transform:uppercase;letter-spacing:1px;">From</p>
                          <p style="margin:0;color:#0f172a;font-size:16px;font-weight:600;">${name}</p>
                        </td>
                      </tr>
                      <tr><td style="height:12px;"></td></tr>
                      <tr>
                        <td style="padding:12px;background:#f8fafc;border-radius:8px;border-left:4px solid #8b5cf6;">
                          <p style="margin:0 0 4px;color:#64748b;font-size:11px;text-transform:uppercase;letter-spacing:1px;">Email</p>
                          <a href="mailto:${email}" style="margin:0;color:#3b82f6;font-size:15px;text-decoration:none;">${email}</a>
                        </td>
                      </tr>
                      <tr><td style="height:12px;"></td></tr>
                      <tr>
                        <td style="padding:12px;background:#f8fafc;border-radius:8px;border-left:4px solid #06b6d4;">
                          <p style="margin:0 0 4px;color:#64748b;font-size:11px;text-transform:uppercase;letter-spacing:1px;">Subject</p>
                          <p style="margin:0;color:#0f172a;font-size:15px;font-weight:500;">${subject}</p>
                        </td>
                      </tr>
                    </table>
                  </td>
                </tr>

                <!-- Message -->
                <tr>
                  <td style="padding:24px 40px 0;">
                    <p style="margin:0 0 12px;color:#64748b;font-size:11px;text-transform:uppercase;letter-spacing:1px;">Message</p>
                    <div style="background:#f8fafc;border-radius:8px;padding:20px;border:1px solid #e2e8f0;">
                      <p style="margin:0;color:#334155;font-size:15px;line-height:1.7;white-space:pre-wrap;">${message}</p>
                    </div>
                  </td>
                </tr>

                <!-- Reply CTA -->
                <tr>
                  <td style="padding:24px 40px;">
                    <a href="mailto:${email}?subject=Re: ${subject}"
                       style="display:inline-block;background:linear-gradient(135deg,#3b82f6,#8b5cf6);color:#ffffff;text-decoration:none;padding:12px 28px;border-radius:8px;font-size:14px;font-weight:600;">
                      Reply to ${name}
                    </a>
                  </td>
                </tr>

                <!-- Footer -->
                <tr>
                  <td style="padding:20px 40px;background:#f8fafc;border-top:1px solid #e2e8f0;">
                    <p style="margin:0;color:#94a3b8;font-size:12px;">
                      Sent from your portfolio · <a href="mailto:${email}" style="color:#3b82f6;">${email}</a>
                    </p>
                  </td>
                </tr>

              </table>
            </td></tr>
          </table>
        </body>
        </html>
      `,
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error("Mail error:", error);
    return NextResponse.json({ error: "Failed to send email." }, { status: 500 });
  }
}
